INSERT INTO categories (id, name, description) VALUES ('math-aptitude', 'Mathematics', 'Quantitative aptitude practice — arithmetic, percentages, ratios, time-speed-distance, algebra, and geometry — for competitive exam and interview prep.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('math-aptitude-bank', NULL, 'Mathematics / Quantitative Aptitude', 'math', 'shared', '2026-11-13T02:45:00.000Z', '2026-11-13T02:45:00.000Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('math-aptitude-bank', 'math-aptitude');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q01', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 0, 'What is the sum of the first 50 natural numbers?', 'Using the formula for the sum of the first n natural numbers, n(n+1)/2: for n = 50, the sum is 50 × 51 / 2 = 1275.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q02', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 1, 'What is the HCF of 36 and 60?', '36 = 2² × 3² and 60 = 2² × 3 × 5. The HCF takes the lowest power of each common prime factor: 2² × 3 = 12.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q03', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 2, 'What is the LCM of 12 and 18?', '12 = 2² × 3 and 18 = 2 × 3². The LCM takes the highest power of each prime factor present: 2² × 3² = 36.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q04', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 3, 'Find the remainder when 2^10 is divided by 7.', '2^10 = 1024. Dividing 1024 by 7 gives 7 × 146 = 1022, leaving a remainder of 1024 − 1022 = 2.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q05', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 4, 'A number, when divided by 15, leaves a remainder of 7. What is the remainder when the same number is divided by 5?', 'The number can be written as 15k + 7 for some integer k. Since 15k is always divisible by 5, the remainder when dividing by 5 comes only from 7 — and 7 divided by 5 leaves a remainder of 2.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q06', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 5, 'Find the smallest number which, when divided by 12, 15, and 20, leaves a remainder of 5 in each case.', 'The required number is (LCM of 12, 15, and 20) + 5. LCM(12, 15, 20) = 60, so the smallest such number is 60 + 5 = 65.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q07', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 6, 'Simplify: 0.75 × 0.75 + 0.75 × 0.25 + 0.25 × 0.25.', 'Computing each term: 0.75 × 0.75 = 0.5625, 0.75 × 0.25 = 0.1875, and 0.25 × 0.25 = 0.0625. Their sum is 0.5625 + 0.1875 + 0.0625 = 0.8125 (equivalently 13/16).', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q08', 'math-aptitude-bank', 'Arithmetic & Number Systems', 0, 7, 'What is the value of the square root of 0.0081?', '0.0081 = 81/10000, and the square root of a fraction is the square root of the numerator over the square root of the denominator: √81/√10000 = 9/100 = 0.09.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q09', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 8, 'A person''s salary is increased by 20% and then decreased by 20%. What is the net percentage change in the salary?', 'Starting from 100, a 20% increase gives 100 × 1.2 = 120, and then a 20% decrease gives 120 × 0.8 = 96. The net change is 96 − 100 = −4, i.e., a net decrease of 4%.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q10', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 9, 'The price of an item is first increased by 25% and then decreased by 20%. What is the final price as a percentage of the original price?', 'Starting from 100, increasing by 25% gives 100 × 1.25 = 125, and then decreasing by 20% gives 125 × 0.8 = 100. So the final price equals 100% of the original — no net change.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q11', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 10, 'A shopkeeper sells an article at a 20% profit. If he had bought it for 10% less and sold it for ₹30 more, he would have gained 40% instead. Find the original cost price.', 'Let the original cost price be ₹x, so the original selling price is 1.2x. The new cost price would be 0.9x, and the new selling price would be 1.2x + 30. A 40% gain on the new cost price means the new selling price equals 1.4 × 0.9x = 1.26x. Setting these equal: 1.26x = 1.2x + 30, so 0.06x = 30, giving x = ₹500.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q12', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 11, 'Find the compound interest on ₹15,000 for 2 years at 20% per annum, compounded annually.', 'The amount after 2 years is 15,000 × (1.2)² = 15,000 × 1.44 = ₹21,600. The compound interest is 21,600 − 15,000 = ₹6,600.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q13', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 12, 'A sum of money amounts to ₹5,445 in 2 years and ₹5,717.25 in 3 years under compound interest. Find the annual rate of interest.', 'The amount for the 3rd year equals the amount for the 2nd year multiplied by (1 + rate/100), since compound interest grows the existing amount by one more year''s interest. So 5,717.25 / 5,445 = 1.05, meaning the rate of interest is 5% per annum.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q14', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 13, 'If the selling price of 20 articles equals the cost price of 25 articles, find the profit percentage.', 'Let the cost price per article be ₹1. Then the selling price of 20 articles (20 × SP) equals the cost price of 25 articles (25 × 1 = 25), so SP = 25/20 = 1.25 per article. Since the cost price per article is ₹1, the profit percentage is (1.25 − 1) × 100 = 25%.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q15', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 14, 'A man buys a watch for ₹1,200 and sells it at a loss of 15%. For how much should he have sold it instead to gain 10%?', 'The cost price is ₹1,200, regardless of what it was actually sold for. To gain 10% instead, the selling price should be 1,200 × 1.1 = ₹1,320.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q16', 'math-aptitude-bank', 'Percentages, Profit & Loss, and Interest', 1, 15, 'Find the single discount equivalent to two successive discounts of 10% and 20%.', 'Applying both discounts to 100: 100 × 0.9 × 0.8 = 72. This means the final price is 72% of the original, which corresponds to a single equivalent discount of 100 − 72 = 28%.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q17', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 16, 'Two numbers are in the ratio 4:5. If 6 is subtracted from each number, the ratio becomes 3:4. Find the two numbers.', 'Let the numbers be 4x and 5x. After subtracting 6 from each: (4x − 6)/(5x − 6) = 3/4. Cross-multiplying: 4(4x − 6) = 3(5x − 6), so 16x − 24 = 15x − 18, giving x = 6. The numbers are 4 × 6 = 24 and 5 × 6 = 30.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q18', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 17, 'The average of 11 numbers is 48. The average of the first 6 of them is 45, and the average of the last 6 is 52. Find the 6th number.', 'The sum of all 11 numbers is 11 × 48 = 528. The sum of the first 6 is 6 × 45 = 270, and the sum of the last 6 is 6 × 52 = 312. Since the 6th number is counted in both groups, adding these two sums double-counts it: 270 + 312 = 582 = 528 + (6th number), so the 6th number is 582 − 528 = 54.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q19', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 18, 'In what ratio must a shopkeeper mix rice costing ₹20 per kg with rice costing ₹30 per kg so that the mixture costs ₹24 per kg?', 'Using the rule of alligation, the ratio of the cheaper to the dearer quantity equals (dearer price − mean price) : (mean price − cheaper price) = (30 − 24) : (24 − 20) = 6 : 4 = 3 : 2. So the ₹20/kg rice and ₹30/kg rice should be mixed in the ratio 3:2.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q20', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 19, 'Ten years ago, the ratio of the ages of A and B was 1:2. Today, the ratio of their ages is 3:5. Find A''s present age.', 'Let A''s age 10 years ago be x and B''s age be 2x. Today their ages are (x + 10) and (2x + 10), and these are in the ratio 3:5: (x + 10)/(2x + 10) = 3/5. Cross-multiplying: 5(x + 10) = 3(2x + 10), so 5x + 50 = 6x + 30, giving x = 20. A''s present age is x + 10 = 30 years.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q21', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 20, 'A mixture of 40 litres of milk and water contains 10% water. How much water should be added to make the water content 20% of the new mixture?', 'The mixture has 40 × 0.1 = 4 litres of water and 36 litres of milk. If w litres of water are added, the new total volume is (40 + w) litres and the new water content is (4 + w) litres. Setting (4 + w)/(40 + w) = 0.2: 4 + w = 8 + 0.2w, so 0.8w = 4, giving w = 5 litres.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q22', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 21, 'The average weight of 25 students in a class is 52 kg. When one student leaves, the average weight becomes 51.5 kg. Find the weight of the student who left.', 'The total weight of all 25 students is 25 × 52 = 1,300 kg. After one student leaves, the total weight of the remaining 24 students is 24 × 51.5 = 1,236 kg. The weight of the student who left is 1,300 − 1,236 = 64 kg.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q23', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 22, 'Vessel A contains milk and water in the ratio 2:3, and Vessel B contains milk and water in the ratio 4:1. In what ratio should the contents of the two vessels be mixed so that the resulting mixture has milk and water in equal proportion (1:1)?', 'The fraction of milk in Vessel A is 2/5 = 0.4, and in Vessel B it is 4/5 = 0.8. Using alligation to reach a target fraction of 0.5: the ratio of Vessel A to Vessel B is (0.8 − 0.5) : (0.5 − 0.4) = 0.3 : 0.1 = 3 : 1. So the vessels should be mixed in the ratio 3:1 (Vessel A to Vessel B).', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q24', 'math-aptitude-bank', 'Ratios, Averages & Mixtures', 2, 23, 'A bag contains ₹1, ₹0.50, and ₹0.25 coins in the ratio 5:6:8, with a total value of ₹210. Find the number of ₹0.50 coins.', 'Let the number of coins be 5x, 6x, and 8x respectively. Their total value is 5x × 1 + 6x × 0.50 + 8x × 0.25 = 5x + 3x + 2x = 10x. Setting 10x = 210 gives x = 21, so the number of ₹0.50 coins is 6 × 21 = 126.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q25', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 24, 'A car covers a distance of 420 km in 6 hours. If the speed is increased by 10 km/h, find the new time taken to cover the same distance.', 'The original speed is 420/6 = 70 km/h. Increasing it by 10 km/h gives a new speed of 80 km/h. The new time taken is 420/80 = 5.25 hours, i.e., 5 hours and 15 minutes.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q26', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 25, 'Two trains, 120 m and 180 m long, run in opposite directions on parallel tracks at 54 km/h and 36 km/h respectively. Find the time they take to cross each other.', 'Since the trains move in opposite directions, their relative speed is 54 + 36 = 90 km/h, which converts to 90 × 5/18 = 25 m/s. The total distance to be covered while crossing is the sum of their lengths, 120 + 180 = 300 m. Time taken = 300/25 = 12 seconds.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q27', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 26, 'A boat travels 24 km upstream in 6 hours and returns downstream in 4 hours. Find the speed of the boat in still water and the speed of the stream.', 'Upstream speed = 24/6 = 4 km/h, and downstream speed = 24/4 = 6 km/h. The boat''s speed in still water is the average of these: (4 + 6)/2 = 5 km/h. The stream''s speed is half their difference: (6 − 4)/2 = 1 km/h.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q28', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 27, 'A can complete a piece of work in 20 days and B can complete it in 30 days. They work together for 5 days, after which A leaves. In how many more days will B finish the remaining work?', 'A''s rate of work is 1/20 per day and B''s rate is 1/30 per day, so their combined rate is 1/20 + 1/30 = 3/60 + 2/60 = 5/60 = 1/12 per day. In 5 days together, they complete 5/12 of the work, leaving 7/12 remaining. B alone, at a rate of 1/30 per day, takes (7/12) ÷ (1/30) = (7/12) × 30 = 17.5 days to finish the rest.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q29', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 28, 'A, B, and C can individually complete a piece of work in 10, 15, and 30 days respectively. If all three work together, how many days will it take to complete the work?', 'Their combined one-day work is 1/10 + 1/15 + 1/30 = 3/30 + 2/30 + 1/30 = 6/30 = 1/5. So working together, they complete the entire work in 5 days.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q30', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 29, 'A train 300 m long is running at a speed of 72 km/h. Find the time it takes to cross a platform that is 500 m long.', 'The train''s speed is 72 km/h = 72 × 5/18 = 20 m/s. To fully cross the platform, the train must cover its own length plus the platform''s length: 300 + 500 = 800 m. The time taken is 800/20 = 40 seconds.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q31', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 30, 'Walking at 4/5 of his usual speed, a man reaches his office 10 minutes later than usual. Find his usual time to cover the distance.', 'If the usual time is t, walking at 4/5 of the usual speed means the new time is t ÷ (4/5) = 1.25t, since time and speed are inversely proportional for a fixed distance. The extra time taken is 1.25t − t = 0.25t, and this equals 10 minutes, so t = 40 minutes.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q32', 'math-aptitude-bank', 'Time, Speed, Distance & Work', 3, 31, 'Excluding stoppages, the speed of a train is 60 km/h; including stoppages, it is 48 km/h. For how many minutes does the train stop, on average, per hour?', 'The difference in speed, 60 − 48 = 12 km/h, represents distance lost to stoppages each hour. At the train''s actual moving speed of 60 km/h, covering this lost 12 km takes 12/60 hour = 0.2 hour = 12 minutes. So the train stops for 12 minutes per hour on average.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q33', 'math-aptitude-bank', 'Algebra & Geometry', 4, 32, 'If x + 1/x = 5, find the value of x² + 1/x².', 'Squaring both sides of x + 1/x = 5 gives x² + 2 + 1/x² = 25, since (x + 1/x)² = x² + 2·x·(1/x) + 1/x² = x² + 2 + 1/x². So x² + 1/x² = 25 − 2 = 23.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q34', 'math-aptitude-bank', 'Algebra & Geometry', 4, 33, 'Solve for x: 2x² − 7x + 3 = 0.', 'Using the quadratic formula with a = 2, b = −7, c = 3: the discriminant is (−7)² − 4(2)(3) = 49 − 24 = 25, and √25 = 5. So x = (7 ± 5)/4, giving x = 3 or x = 0.5.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q35', 'math-aptitude-bank', 'Algebra & Geometry', 4, 34, 'Find the area of a triangle whose sides are 13 cm, 14 cm, and 15 cm.', 'Using Heron''s formula, the semi-perimeter is s = (13 + 14 + 15)/2 = 21. The area is √(s(s−a)(s−b)(s−c)) = √(21 × 8 × 7 × 6) = √7056 = 84 cm².', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q36', 'math-aptitude-bank', 'Algebra & Geometry', 4, 35, 'The circumference of a circle is 44 cm. Find its area. (Use π = 22/7.)', 'From the circumference formula, 2πr = 44, so r = 44 ÷ (2 × 22/7) = 44 × 7/44 = 7 cm. The area is πr² = 22/7 × 49 = 154 cm².', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q37', 'math-aptitude-bank', 'Algebra & Geometry', 4, 36, 'The three angles of a triangle are in the ratio x : 2x : 3x (in degrees). Find the value of x.', 'The angles of a triangle always sum to 180°, so x + 2x + 3x = 6x = 180, giving x = 30.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q38', 'math-aptitude-bank', 'Algebra & Geometry', 4, 37, 'A 17-metre ladder leans against a wall with its foot 8 metres away from the base of the wall. Find the height at which the ladder touches the wall.', 'The ladder, the wall, and the ground form a right triangle, so by the Pythagorean theorem the height is √(17² − 8²) = √(289 − 64) = √225 = 15 metres.', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q39', 'math-aptitude-bank', 'Algebra & Geometry', 4, 38, 'Factorize: x² − 5x + 6.', 'Looking for two numbers that multiply to 6 and add to −5 gives −2 and −3. So x² − 5x + 6 factorizes as (x − 2)(x − 3).', '2026-11-13T02:45:00.000Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('math-q40', 'math-aptitude-bank', 'Algebra & Geometry', 4, 39, 'The volume of a cube is 512 cm³. Find its total surface area.', 'The side length is the cube root of 512, which is 8 cm, since 8³ = 512. The total surface area of a cube is 6 × (side)² = 6 × 64 = 384 cm².', '2026-11-13T02:45:00.000Z');
